## Calculo integral de nomina
if (salarioMensual <= 0) { throw "SALARIO_INVALIDO"; }
if (diasMes <= 0) { throw "DIAS_INVALIDOS"; }
if (diasTrabajados < 0 || diasTrabajados > diasMes) { throw "DIAS_TRABAJADOS_INVALIDOS"; }
let salarioBase = salarioMensual * diasTrabajados / diasMes;
let bonificacionAntiguedad = 0;
if (aniosAntiguedad >= 10) { bonificacionAntiguedad = salarioBase * 0.12; } elsif (aniosAntiguedad >= 5) { bonificacionAntiguedad = salarioBase * 0.08; } elsif (aniosAntiguedad >= 2) { bonificacionAntiguedad = salarioBase * 0.04; }
let bonificacionCargo = 0;
if (tipoEmpleado == "TECNICO") { bonificacionCargo = salarioBase * 0.05; } elsif (tipoEmpleado == "SUPERVISOR") { bonificacionCargo = salarioBase * 0.1; } elsif (tipoEmpleado == "GERENTE") { bonificacionCargo = salarioBase * 0.15; }
let bonificacionDesempeno = 0;
if (calificacionDesempeno >= 95) { bonificacionDesempeno = salarioBase * 0.15; } elsif (calificacionDesempeno >= 90) { bonificacionDesempeno = salarioBase * 0.1; } elsif (calificacionDesempeno >= 80) { bonificacionDesempeno = salarioBase * 0.05; }
let detalleHorasExtras = seq.list();
let totalHorasExtras = 0;
for hora in horasExtras { let multiplicador = 0; if (hora.tipo == "DIURNA") { multiplicador = 1.5; } elsif (hora.tipo == "NOCTURNA") { multiplicador = 2; } elsif (hora.tipo == "FERIADO") { multiplicador = 2.5; } else { throw "TIPO_HORA_INVALIDO"; } if (hora.horas > 0) { let importe = salarioMensual / 240 * hora.horas * multiplicador; totalHorasExtras = totalHorasExtras + importe; seq.add(detalleHorasExtras, seq.map("tipo", hora.tipo, "horas", hora.horas, "multiplicador", multiplicador, "importe", importe)); } }
let totalBonificaciones = bonificacionAntiguedad + bonificacionCargo + bonificacionDesempeno;
let ingresosBrutos = salarioBase + totalBonificaciones + totalHorasExtras;
let descuentoProgresivo = 0;
if (ingresosBrutos > 2000) { descuentoProgresivo = (2000 - 1500) * 0.05 + (ingresosBrutos - 2000) * 0.08; } elsif (ingresosBrutos > 1500) { descuentoProgresivo = (ingresosBrutos - 1500) * 0.05; }
let detalleDescuentos = seq.list();
let totalDescuentosAdicionales = 0;
for descuento in descuentosAdicionales { if (descuento.valor < 0) { throw "DESCUENTO_INVALIDO"; } totalDescuentosAdicionales = totalDescuentosAdicionales + descuento.valor; seq.add(detalleDescuentos, seq.map("concepto", descuento.concepto, "valor", descuento.valor)); }
let totalDescuentos = descuentoProgresivo + totalDescuentosAdicionales;
let salarioNeto = ingresosBrutos - totalDescuentos;
let clasificacion = salarioNeto < 0 ? "ERROR_SALDO_NEGATIVO" : salarioNeto < 1000 ? "NOMINA_BAJA" : salarioNeto <= 2000 ? "NOMINA_MEDIA" : "NOMINA_ALTA";
return seq.map("salarioBase", salarioBase, "bonificacionAntiguedad", bonificacionAntiguedad, "bonificacionCargo", bonificacionCargo, "bonificacionDesempeno", bonificacionDesempeno, "totalBonificaciones", totalBonificaciones, "totalHorasExtras", totalHorasExtras, "detalleHorasExtras", detalleHorasExtras, "ingresosBrutos", ingresosBrutos, "descuentoProgresivo", descuentoProgresivo, "detalleDescuentos", detalleDescuentos, "totalDescuentosAdicionales", totalDescuentosAdicionales, "totalDescuentos", totalDescuentos, "salarioNeto", salarioNeto, "clasificacion", clasificacion);
